spawn(executable, args, {
        cwd: process.cwd(),
        stdio: 'pipe',
        env: {
          PATH: '/home/ricardo/.nvm/versions/node/v22.23.2/bin:/usr/local/bin:/usr/bin:/bin',
          HOME: directory,
          TMPDIR: directory,
          XDG_CONFIG_HOME: resolve(directory, 'config'),
          XDG_DATA_HOME: resolve(directory, 'data'),
          LANG: 'C.UTF-8'
        }
      })

child.stdout.on('data', (data) => {
        stdout += String(data)
        if (Buffer.byteLength(stdout) > 1048576) child.kill('SIGKILL')
        for (const line of String(data).split('\n')) {
          try {
            const msg = JSON.parse(line) as Record<string, unknown>
            if (msg.point) messages.push(msg)
          } catch {
            /* Partial lines handled by the accumulated buffer below. */
          }
        }
        for (const line of stdout.split('\n')) {
          try {
            const msg = JSON.parse(line) as Record<string, unknown>
            if (msg.point && !messages.some((m) => m.point === msg.point))
              messages.push(msg)
          } catch {
            /* Diagnostic lines are preserved raw. */
          }
        }
        for (const listener of listeners) listener()
      })

child.once('error', (error) => {
        spawnError = error
        for (const listener of listeners) listener()
      })

child.once('close', () => {
        for (const listener of listeners) listener()
      })

spawn(executable, args, {
    cwd: process.cwd(),
    stdio: 'pipe',
    env: {
      PATH: '/home/ricardo/.nvm/versions/node/v22.23.2/bin:/usr/local/bin:/usr/bin:/bin',
      HOME: home,
      TMPDIR: temporary,
      XDG_CONFIG_HOME: resolve(home, 'config'),
      XDG_DATA_HOME: resolve(home, 'data'),
      LANG: 'C.UTF-8'
    }
  })

child.stdout.on('data', (data: Buffer) => {
    const chunk = data.toString()
    stdout += chunk
    pending += chunk
    if (Buffer.byteLength(stdout) > 16 * 1024 * 1024) child.kill('SIGKILL')
    let end: number
    while ((end = pending.indexOf('\n')) !== -1) {
      const line = pending.slice(0, end)
      pending = pending.slice(end + 1)
      try {
        const message = JSON.parse(line) as Row
        if (typeof message.point === 'string')
          messages.push({ ...message, receivedAt: new Date().toISOString() })
      } catch {
        /* Preserve non-JSON diagnostics in the raw stdout. */
      }
    }
    for (const listener of listeners) listener()
  })

child.stderr.on('data', (data: Buffer) => {
    stderr += data.toString()
    if (Buffer.byteLength(stderr) > 2 * 1024 * 1024) child.kill('SIGKILL')
  })

child.once('error', (error) => {
    spawnError = error
    for (const listener of listeners) listener()
  })

child.once('close', () => {
    for (const listener of listeners) listener()
  })

spawn(executable, ['-e', scripts[script]], {
    cwd,
    env: {
      LANG: 'C.UTF-8',
      HOME: home,
      TMPDIR: home,
      XDG_CONFIG_HOME: join(home, 'config'),
      XDG_DATA_HOME: join(home, 'data')
    },
    stdio: 'pipe'
  })

